create or replace function public.run_representative_rule_suite_golden_v1(p_release_code text default 'runtime-structural-v1.19') returns uuid language plpgsql security invoker set search_path='public','pg_catalog' as $function$ declare v_release_id uuid; v_engine text; v_batch uuid:=gen_random_uuid(); g record; v_audit jsonb; v_item jsonb; v_pass boolean; v_actual jsonb; v_expected_state text; begin select id,engine_version into v_release_id,v_engine from public.grammar_runtime_releases where code=p_release_code; if v_release_id is null then raise exception 'Release % not found',p_release_code; end if; v_audit:=public.audit_representative_rule_suite_v1(); for g in select * from public.grammar_golden_tests where code like 'representative_rule_suite_v1.%' and status in ('implemented','passed') order by code loop v_pass:=false; v_actual:='{}'::jsonb; if g.code like 'representative_rule_suite_v1.invariant.%' then v_actual:=v_audit->'summary'; v_pass:=not exists(select 1 from jsonb_each(g.expected_language_graph) e where (v_actual->e.key) is distinct from e.value); else select x into v_item from jsonb_array_elements(v_audit->'items') x where (x->>'ordinal')::int=(g.input_fixture->>'ordinal')::int limit 1; v_expected_state:=g.expected_language_graph->>'expected_current_state'; v_actual:=coalesce(v_item,'{}'::jsonb); v_pass:=v_item is not null and v_item->>'candidate_id'=g.input_fixture->>'candidate_id' and v_item->>'source_status' in ('verified','source_verified') and case v_expected_state when 'compiled_operator_expected' then v_item->>'actual_current_state'='compiled_execution_plane_closed' when 'compiled_but_execution_adapter_required' then v_item->>'actual_current_state'='compiled_pattern_not_closed_in_execution_plane_v1' when 'compiled_mixed_support' then v_item->>'actual_current_state'='compiled_mixed_closed_and_unclosed' when 'compiled_but_upstream_fields_deferred' then v_item->>'actual_current_state'='compiled_pattern_not_closed_in_execution_plane_v1' when 'source_consumed_but_not_compiled' then v_item->>'actual_current_state'='source_or_runtime_capability_without_compiled_rule' when 'source_consumed_partial_semantics' then v_item->>'actual_current_state'='source_or_runtime_capability_without_compiled_rule' when 'runtime_capability_exists_not_rule_driven' then v_item->>'actual_current_state'='source_or_runtime_capability_without_compiled_rule' when 'source_to_morphology_mapping_required' then v_item->>'actual_current_state'='source_or_runtime_capability_without_compiled_rule' when 'reference_or_interpretive' then v_item->>'actual_current_state'='reference_or_interpretive_not_runtime_compiled' when 'new_generic_capability_required' then v_item->>'actual_current_state'='named_generic_capability_missing' else false end; end if; insert into public.grammar_golden_test_runs(golden_test_id,runtime_release_id,evaluator_version,engine_version,passed,input_snapshot,actual_result,diff,finished_at,run_batch_id) values(g.id,v_release_id,'representative-rule-suite-evaluator-v1',v_engine,v_pass,g.input_fixture,v_actual,case when v_pass then '{}'::jsonb else jsonb_build_object('expected',g.expected_language_graph,'actual',v_actual) end,clock_timestamp(),v_batch); update public.grammar_golden_tests set last_result=jsonb_build_object('passed',v_pass,'actual',v_actual,'batch_id',v_batch),last_run_at=clock_timestamp(),status=case when v_pass then 'passed' else 'implemented' end where id=g.id; end loop; return v_batch; end; $function$;
